B.aXg=new A.hh("2000-01-05","\uccab \uc548\uac74: \ub108\ubb34 \ube68\ub9ac \uc815\ud55c \uc77c","\uc544\ub9b0\uc774 \uc790\ub9ac \ubc30\uce58\ub97c 4\ubd84\uc5d0 \ub05d\ub0b8 \uac78 \uc548\uac74\uc73c\ub85c \uc62c\ub838\ub2e4. \uc774\uc11c\uac00 \uc190\uc744 \ub4e4\ub824\ub2e4 \ub9d0\uc558\ub358 \uc774\uc720\ub97c \ub9d0\ud558\uace0, \uc5f4 \uba85\uc740 \ub2e4\uc74c\ubd80\ud130 \uacb0\uc815 \ub4a4\uc5d0 \ud55c \uc0ac\ub78c\uc529 \uc774\ub984\uc744 \ubd88\ub7ec \ud655\uc778\ud558\uae30\ub85c \uc815\ud588\ub2e4.","\uccab \uc548\uac74",B.iI,4286356694,u.u)
B.aXp=new A.hh("2000-01-07","\uac80\uc0b0 \uaddc\uce59\uc774 \uc7a5\ubd80\uc5d0 \ub4e4\uc5b4\uac14\ub2e4","\ud559\uc900\uc774 \uc8fc\ubb38 \uc804 \ucd5c\uc545 \uc190\uc2e4\uc744 \uba3c\uc800 \uc801\ub294 \uce78\uc744 \uc6d0\uc7a5\uc5d0 \ub9cc\ub4e4\uc5c8\ub2e4. \ucc98\uc74c\uc5d4 \ubc88\uac70\ub86d\ub2e4\uace0 \ud588\uc9c0\ub9cc \uadf8 \uce78\uc744 \ube44\uc6b4 \uc0ac\ub78c\uc758 \uc190\uc2e4\uc774 \ub354 \ucef8\ub2e4\ub294 \uac78 \uc544\ubb34\ub3c4 \ubc18\ubc15\ud558\uc9c0 \ubabb\ud588\ub2e4.","\uac80\uc0b0",B.qe,4284317603,u.n)
B.aXo=new A.hh("2000-01-10","\uccab \uc8fc \uc7a5\ubd80 \ub300\uc870","\uc11c\uc544\uac00 \uc5f4 \uad8c\uc758 \uc7a5\ubd80\ub97c \ub098\ub780\ud788 \ub193\uace0 \uccab \uc8fc\ub97c \ub9de\ucdc4\ub2e4. \uc218\uc775\uc774 \uc544\ub2c8\ub77c \uc801\uc9c0 \uc54a\uc740 \uce78\uc774 \uba87 \uac1c\uc778\uc9c0\ub97c \uba3c\uc800 \uc14c\uace0, \ube48 \uce78\uc774 \uac00\uc7a5 \uc801\uc740 \uc0ac\ub78c\uc740 1\ub4f1\uc774 \uc544\ub2c8\uc5c8\ub2e4.","\uc8fc\uac04 \ub300\uc870",B.ee,4293895260,u.u)
B.aXl=new A.hh("2000-01-14","\uc2dc\uacc4 \ub2e4\uc12f \uac1c\uac00 \uac19\uc544\uc84c\ub2e4","\uc9c0\uc548\uc774 \ud2b8\ub808\uc774\ub529 \ud50c\ub85c\uc5b4 \uc2dc\uacc4\ub97c \uc804\ubd80 \ub9de\ucdc4\ub2e4. \uc18c\uc720\uc790 \ud655\uc778\uacfc \uc804\uc6d0 \ucc28\ub2e8, \ub450 \uba85 \uc785\ud68c\uae4c\uc9c0 \uc9c0\ucf1c\uc11c \uc774\ubc88\uc5d0\ub294 \uc544\ubb34\ub3c4 \ub180\ub77c\uc9c0 \uc54a\uc558\ub2e4. \uc21c\uc11c\uac00 \uaddc\uce59\uc774 \ub41c \uccab \uc0ac\ub840\ub85c \uae30\ub85d\ub410\ub2e4.","\uc815\ube44",B.iI,4287605176,"assets/images/cinematic_soft_painted/decimal/bg_decimal_electronics_workshop_2000_v1.png")
B.aXm=new A.hh("2000-01-21","\uc218\uc544\uc758 \uc18c\ubb38 \uacf5\ucc45","\uc218\uc544\uac00 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub290 \ud68c\uc0ac \uc774\ub984\uc744 \uc5b4\ub514\uc11c \ucc98\uc74c \uaebc\ub0b4\ub294\uc9c0 \uc801\uae30 \uc2dc\uc791\ud588\ub2e4. \ucc44\uc544\uac00 \uadf8 \uacf5\ucc45\uc5d0 \uc5b8\uc81c \ub4e4\uc5c8\ub294\uc9c0 \uce78\uc744 \ud558\ub098 \ub354 \uadf8\uc5c8\ub2e4. \uba3c\uc800 \ub4e3\ub294 \uac83\uacfc \uba3c\uc800 \uc544\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4\uace0.","\uc18c\ubb38 \uacf5\ucc45",B.qe,4293233576,u.u)
B.aXt=new A.hh("2000-01-31","\uccab \ub2ec \uacb0\uc0b0","\ud55c\uc11c\uc724\uc774 \uccab \ub2ec \ud658\uc218\uae08\uacfc \uc790\ub9bd\uc801\ub9bd\uae08\uc744 \uac01\uac01 \uc77d\uc5b4 \uc92c\ub2e4. \ubc88 \uc0ac\ub78c\ub3c4 \uc783\uc740 \uc0ac\ub78c\ub3c4 \uc788\uc5c8\uc9c0\ub9cc \ubc25\uacfc \uc7a0\uc790\ub9ac\ub294 \uadf8\ub300\ub85c\uc600\ub2e4. \uacc4\uc57d\uc11c \uccab \uc7a5\uc774 \uc0ac\uc2e4\uc774\ub77c\ub294 \uac8c \ud655\uc778\ub41c \ub0a0.","\uc6d4 \uacb0\uc0b0",B.ee,4294948941,u.u)
B.aXe=new A.hh("2000-02-25","\ucc3d\uace0\uc5d0 \ub0a8\uc544 \uc788\ub358 1996\ub144 \uc885\uc774","\uc11c\uc544\uac00 \uae30\ub85d \ubcf4\uad00\uc2e4\uc5d0\uc11c \ud3d0\uae30\ub85c \uc801\ud600 \uc788\ub358 1996\ub144 \uc2dc\ud5d8\uc9c0\ub97c \ucc3e\uc558\ub2e4. \uc138 \ud574 \uc804 \uc885\uc774 \uaddc\uaca9\uc774 \uc65c \ub2ec\ub790\ub294\uc9c0 \ub4dc\ub514\uc5b4 \ub9de\uc544\ub5a8\uc5b4\uc84c\uace0, \ub3c4\uc724\uc11d\uc740 \uae30\ub85d\uc744 \uace0\uce58\ub294 \ub300\uc2e0 \ubc1c\uacac\uc790 \uc774\ub984\uc744 \uc801\uc5c8\ub2e4.","1996\ub144",B.ee,4288449223,u.A)
B.aXu=new A.hh("2000-03-24","\uacbd\uacc4\uac00 \uaddc\uc815\uc774 \ub410\ub2e4","\uc774\uc11c\uac00 \ub9d0\ud55c \u201c\uba3c\uc800 \ubb3c\uc5b4\ubcf4\uae30\u201d\uac00 \uc13c\ud130 \uc0dd\ud65c \uaddc\uc815 3\uc870\ub85c \ub4e4\uc5b4\uac14\ub2e4. \uace0\uce58\ub294 \uc0ac\ub78c\uacfc \uc8fc\uc778\uc774 \uac19\uc774 \ubcf4\ub294 \uc870\ud56d\uc774\ub77c \uc9c0\uc548\uc774 \uac00\uc7a5 \uba3c\uc800 \uc11c\uba85\ud588\ub2e4.","\uc0dd\ud65c \uaddc\uc815",B.iI,4291398282,u.u)
B.aXd=new A.hh("2000-04-14","\ubaa8\ub978\ub2e4\uace0 \ub9d0\ud560 \uad8c\ub9ac","\ud558\uc740\uc774 \u201c\ubaa8\ub978\ub2e4\uace0 \ub2f5\ud55c \uc0ac\ub78c\uc744 \ucc3d\ud53c\ud558\uac8c \ub9cc\ub4e4\uc9c0 \uc54a\uae30\u201d\ub97c \ud68c\uc758 \uaddc\uce59\uc5d0 \ub123\uc790\uace0 \ud588\ub2e4. \uadf8 \uc8fc\ubd80\ud130 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\uac00 \ud68c\uc758\uc5d0 \uc62c\ub77c\uc624\ub294 \ud69f\uc218\uac00 \ub298\uc5c8\ub2e4.","\ud68c\uc758 \uaddc\uce59",B.iI,4292912068,u.u)
B.aXn=new A.hh("2000-06-30","\uc0c1\ubc18\uae30 \uac10\uc0ac","\uc870\ubbfc\uacbd\uc774 \ubc18\ub144 \uce58 \uae30\ub85d\uc744 \uc5f4\ub78c\ud588\ub2e4. \ud655\uc778\ud55c \uac74 \uc218\uc775\ub960\uc774 \uc544\ub2c8\ub77c \uc911\ub2e8\uad8c\uc744 \uc4f4 \uc0ac\ub78c\uc774 \uc788\uc5c8\ub294\uc9c0, \uadf8\ub54c \uc544\ubb34\ub3c4 \ubd88\uc774\uc775\uc744 \ubc1b\uc9c0 \uc54a\uc558\ub294\uc9c0\uc600\ub2e4.","\uac10\uc0ac",B.ee,4286556299,u.A)
B.aXh=new A.hh("2000-09-01","\uae68\uc9c0\ub294 \uc870\uac74 \uac8c\uc2dc\ud310","\ucc44\uc544\uac00 \ub77c\uc6b4\uc9c0 \ubcbd\uc5d0 \uac00\uc124\uacfc \ud568\uaed8 \u201c\uc774 \uac00\uc124\uc774 \ud2c0\ub9ac\ub294 \uc870\uac74\u201d\uc744 \ubd99\uc774\ub294 \uce78\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc624\uc9c0\uc6b0\uac00 \uac00\uc7a5 \ub9ce\uc774 \ubd99\uc600\uace0, \uac00\uc7a5 \ub9ce\uc774 \uc9c0\uc6b4 \uac83\ub3c4 \uadf8\uc600\ub2e4.","\uac00\uc124 \uac8c\uc2dc\ud310",B.qe,4285433528,u.u)
B.aXc=new A.hh("2000-12-29","\uccab \ud574\uac00 \ub2eb\ud614\ub2e4","2000\ub144 \ub9c8\uc9c0\ub9c9 \uac70\ub798\uc77c. \uc5f4 \uba85\uc758 \uc7a5\ubd80 \uccab \uad8c\uc774 \ub2e4 \ucc3c\ub2e4. \uc544\ubb34\ub3c4 \uccab \uc7a5\uc758 50,000\uc6d0\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\uc558\uace0, \uc11c\uc544\ub294 \ub9c8\uc9c0\ub9c9 \uc904 \uc544\ub798\uc5d0 \ub2e4\uc74c \uad8c \ubc88\ud638\ub9cc \uc801\uc5c8\ub2e4.","\uccab \ud574 \ub9c8\uac10",B.ee,4294948941,u.n)
B.aXf=new A.hh("2001-04-16","15\uc0b4, \ub450 \ubc88\uc9f8 \ubd04","\ud504\ub85c\uc81d\ud2b8 \uc7ac\uac00\ub3d9 2\uc8fc\ub144. \ud55c\uaddc\uc9c4\uc740 \uc5ec\uc804\ud788 \uc218\uc775\ub960\ubcf4\ub2e4 \uc911\ub2e8\uad8c\uc744 \uba3c\uc800 \ubcf4\uace0\ubc1b\uc558\ub2e4. \uc5f4 \uba85 \uc911 \ub204\uad6c\ub3c4 \uc544\uc9c1 \ub098\uac00\uc9c0 \uc54a\uc558\ub2e4\ub294 \ubb38\uc7a5\uc774 \ubcf4\uace0\uc11c \uccab \uc904\uc774\uc5c8\ub2e4.","2\uc8fc\ub144",B.ee,4288449223,u.A)
