B.a6Y=new A.lw("lee_jian","\uc774\uc9c0\uc548",1987,3,28,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ISTP","\uccb4\uacb0 \uad6c\uc870 \xb7 \ucd08\ub2e8\uae30 \ub300\uc751 \ub2f4\ub2f9","\uc190\uc73c\ub85c \uc9c1\uc811 \ud655\uc778\ud574\uc57c \ub0a9\ub4dd\ud558\ub294 \uc870\uc6a9\ud558\uace0 \uc7ac\ube60\ub978 \uc218\ub9ac\uad11.","\ubb38\uc81c\ub97c \ud55c\ub3d9\uc548 \uc870\uc6a9\ud788 \ubcf4\ub2e4\uac00 \uc6d0\uc778\uc774 \ubcf4\uc774\uba74 \ubc14\ub85c \uc190\uc744 \ub304\ub2e4. \ud63c\uc790 \uc9d1\uc911\ud558\ub294 \uc2dc\uac04\uc744 \uc88b\uc544\ud558\uc9c0\ub9cc \ub204\uad70\uac00 \uc815\ub9d0 \uace4\ub780\ud560 \ub54c\ub294 \uae34 \uc124\uba85\ubcf4\ub2e4 \uba3c\uc800 \uace0\uccd0 \uc900\ub2e4.","\ub77c\ub514\uc624, \uc791\uc740 \uacf5\uad6c, \ubd84\ud574 \uac00\ub2a5\ud55c \uae30\uacc4, \uace0\uc7a5 \uc6d0\uc778 \ucc3e\uae30","\ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \uc791\ub3d9 \uc6d0\ub9ac\uc640 \ud655\uc778 \uac00\ub2a5\ud55c \uc6d0\uc778\uc73c\ub85c \uc798\uac8c \ub098\ub208\ub2e4.","\uad11\uace0\ubcf4\ub2e4 \uc2e4\uc81c \uc81c\ud488\uacfc \uc791\ub3d9 \uc6d0\ub9ac\ub97c \uc2dc\ud5d8\ud558\uace0 \uacb0\ud568\uc774 \ubc29\uce58\ub418\uba74 \ud310\ub2e4.","\ub9d0\uc740 \uc9e7\uc544\ub3c4 \ud568\uaed8 \uc791\uc5c5\ud558\uace0 \uc120\uc81c\uc801\uc73c\ub85c \ub3c4\uc640\uc8fc\ub294 \ud589\ub3d9\uc73c\ub85c \uce5c\ubc00\ud568\uc744 \ubcf4\uc778\ub2e4.",B.b64,4286037224,u.cv)
B.b5R=s(["\uac10\uac01","\uc81c\uc791","\uacbd\uacc4"],t.s)
B.a71=new A.lw("choi_iseo","\ucd5c\uc774\uc11c",1987,5,4,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ISFP","\ucc28\ud2b8 \ub9ac\ub4ec \xb7 \uc774\uc0c1 \uc9d5\ud6c4 \ub2f4\ub2f9","\uc0c9\uacfc \uc7ac\uc9c8, \ub2f9\uc0ac\uc790\uc758 \ud3b8\uc548\ud568\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uc12c\uc138\ud55c \uc81c\uc791\uc790.","\ub0a8\ub4e4\uc774 \uc88b\uc544\ud558\ub294 \uac83\uacfc \uc790\uc2e0\uc774 \uc88b\uc544\ud558\ub294 \uac83\uc744 \ubd84\uba85\ud788 \uad6c\ubd84\ud55c\ub2e4. \uc870\uc6a9\ud558\uc9c0\ub9cc \uac1c\uc778\uc758 \uc120\ud0dd\uacfc \uacbd\uacc4\ub97c \uac00\ubccd\uac8c \ub118\ub294 \ud589\ub3d9\uc5d0\ub294 \ub2e8\ud638\ud558\ub2e4.","\ucc9c \uc870\uac01, \uc0c9 \uc870\ud569, \uc190\ubc14\ub290\uc9c8, \uc624\ub798 \uc368\uc11c \uc190\uc5d0 \uc775\uc740 \ubb3c\uac74","\uc22b\uc790\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\uc6a9\uac10\uacfc \uc0ac\ub78c\uc758 \ubd88\ud3b8\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubc1c\uacac\ud55c\ub2e4.","\uc0ac\ub78c\uc774 \uc2e4\uc81c\ub85c \uc4f0\uae30 \ud3b8\ud55c \uc81c\ud488\uc778\uc9c0, \uc720\ud589 \ub4a4\uc5d0\ub3c4 \ucde8\ud5a5\uc774 \ub0a8\ub294\uc9c0 \uc0b4\ud540\ub2e4.","\ucde8\ud5a5\uc744 \uac15\uc694\ud558\uc9c0 \uc54a\uace0 \uc11c\ub85c\uc758 \uc120\ud0dd\uc744 \uc874\uc911\ud560 \ub54c \uac00\uc7a5 \ud3b8\ud558\uac8c \uac00\uae4c\uc6cc\uc9c4\ub2e4.",B.b5R,4290088168,u.gt)
B.b1t=s(["\uc2e4\ud589\ub825","\uc815\ub9ac","\ub9c8\uac10"],t.s)
B.a72=new A.lw("jung_arin","\uc815\uc544\ub9b0",1987,6,21,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ESTJ","\uc778\uc218 \uc2e4\ud589 \xb7 \uc6b4\uc601 \ud1b5\ud569 \ub2f4\ub2f9","\ud750\ub9b0 \uc57d\uc18d\uc744 \ub2f4\ub2f9\uacfc \ub9c8\uac10\uc774 \uc788\ub294 \ud589\ub3d9\uc73c\ub85c \ubc14\uafb8\ub294 \ud604\uc7a5 \ubc18\uc7a5.","\ub204\uac00 \uc5b8\uc81c \ubb34\uc5c7\uc744 \ud560\uc9c0 \ubd88\ubd84\uba85\ud55c \uc0c1\ud669\uc744 \uac00\uc7a5 \ub2f5\ub2f5\ud574\ud55c\ub2e4. \ub9d0\uc774 \ub2e8\ud638\ud574 \uce5c\uad6c\ub97c \ubab0\uc544\ubd99\uc77c \ub54c\ub3c4 \uc788\uc9c0\ub9cc, \uc798\ubabb\uc744 \uc54c\uba74 \uacc4\ud68d\ubd80\ud130 \ubc14\ub85c \uace0\uce5c\ub2e4.","\uccb4\ud06c\ud45c, \uc815\ud655\ud55c \uc2dc\uac04 \uc57d\uc18d, \ub05d\ub09c \uc77c\uc5d0 \uae0b\ub294 \uad75\uc740 \uc644\ub8cc\uc120","\uacb0\uc815\ub41c \uc77c\uc744 \ub2f4\ub2f9\xb7\uc21c\uc11c\xb7\ub9c8\uac10\uc73c\ub85c \ub098\ub220 \uc2e4\uc81c \ud589\ub3d9\uae4c\uc9c0 \ub04c\uace0 \uac04\ub2e4.","\uacc4\ud68d\ubcf4\ub2e4 \uc2e4\ud589 \uc2e4\uc801\uacfc \ub9c8\uac10 \uc900\uc218, \ubc18\ubcf5 \uac00\ub2a5\ud55c \uc6b4\uc601 \ub2a5\ub825\uc744 \ud655\uc778\ud55c\ub2e4.","\ub3cc\ub824 \ub9d0\ud558\uae30\ubcf4\ub2e4 \uac00\ub2a5\ud55c \uc2dc\uac04\uacfc \ud589\ub3d9\uc744 \uc815\ud655\ud788 \uc57d\uc18d\ud558\ub294 \uc0ac\ub78c\uc744 \uc2e0\ub8b0\ud55c\ub2e4.",B.b1t,4294939750,u.g)
B.bb8=s(["\ubc30\ub824","\ud569\uc758","\uc751\uc6d0"],t.s)
B.a73=new A.lw("park_haeun","\ubc15\ud558\uc740",1987,8,8,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ENFJ","\uc815\ubcf4\ub9dd \xb7 \ud611\uc0c1 \xb7 \uad00\uacc4 \uc704\ud5d8 \ub2f4\ub2f9","\ub9d0\ud558\uc9c0 \ubabb\ud55c \uce5c\uad6c\ub97c \ubc1c\uacac\ud558\uba74 \uadf8\ub0e5 \uc9c0\ub098\uce58\uc9c0 \ubabb\ud558\ub294 \ub2e4\uc815\ud55c \uc870\uc815\uc790.","\uc9d1\ub2e8\uc758 \ubd84\uc704\uae30\uc640 \ud63c\uc790 \uc785\uc744 \ub2eb\uc740 \uce5c\uad6c\ub97c \ud568\uaed8 \uc0b4\ud540\ub2e4. \ubaa8\ub450\ub97c \ube68\ub9ac \ud654\ud574\uc2dc\ud0a4\ub824\ub2e4 \uc2e4\uc218\ud560 \ub54c\ub3c4 \uc788\uc9c0\ub9cc, \uc0c1\ub300\uc758 \uac70\uc808\uc744 \ub4e4\uc73c\uba74 \uba48\ucd94\ub294 \ubc95\uc744 \ubc30\uc6b0\uace0 \uc788\ub2e4.","\ud568\uaed8 \uba39\ub294 \uac04\uc2dd, \uc5ed\ud560 \ub098\ub204\uae30, \uce5c\uad6c\uac00 \uc790\uae30 \uc758\uacac\uc744 \ub9d0\ud558\ub294 \uc21c\uac04","\uc11c\ub85c \ub2e4\ub978 \uc785\uc7a5\uc744 \ub9d0\ud560 \uc218 \uc788\uac8c \ub9cc\ub4e4\uace0 \uac01\uc790 \uc798\ud560 \uc5ed\ud560\uc744 \ucc3e\uc544 \uc900\ub2e4.","\uc9c1\uc6d0\uacfc \uace0\uac1d\uc774 \uc2e4\uc81c\ub85c \uc624\ub798 \uba38\ubb3c \uc218 \uc788\ub294 \uc870\uc9c1\uc778\uc9c0 \uba3c\uc800 \uad00\ucc30\ud55c\ub2e4.","\uc0c1\ub300\uac00 \uc6d0\ud558\ub294 \ub3c4\uc6c0\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubb3b\uace0, \uac00\uae4c\uc6cc\uc9c8\uc218\ub85d \uc790\uae30 \ud544\uc694\ub3c4 \uc194\uc9c1\ud788 \ub9d0\ud55c\ub2e4.",B.bb8,4294934427,u.b4)
