B.chx=new A.oQ("assets/images/production_soft_painted/lee_jian/02_playful_wink_v2.png",u.aP,"PC\ub294 \uacf5\uc6a9 \ucef4\ud4e8\ud130\uc2e4\uc5d0 \uc788\uc5b4. \ub2e4 \uac19\uc774 \uc4f0\ub294 \uc790\ub9ac\ub2c8\uae4c \uc815\ub9ac\ud558\uace0 \uac00\uc790.","\uc22b\uc790 \ud280\ub294 \ub370\ub294 \uc6d0\uc778\uc774 \uc788\uc5b4. \ucc28\ud2b8\ubcf4\ub2e4 \uccb4\uacb0\ubd80\ud130 \ubcf4\uba74 \ube68\ub77c.","\uae30\uacc4\ub294 \uaed0\uace0 \uacf5\uad6c\ub3c4 \uc14c\uc5b4. \uc774\uc81c \ub124\uac00 \ubb58 \ud655\uc778\ud588\ub294\uc9c0 \ub4e4\uc73c\uba74 \ub3fc.","\uc815\ube44\ud560 \uac74 \ub05d\ub0c8\uc5b4. \ubd80\ud488 \uad6c\uacbd \uac08 \uac70\uba74 \uc0ac\ub78c \uc801\uc744 \ub54c \uac00\uc790."," \ub124\uac00 \uc606\uc5d0\uc11c \uc21c\uc11c\ub9cc \ub9de\ucdb0 \uc8fc\uba74 \uae08\ubc29 \ub05d\ub098."," \ub124 \ubaab\uc740 \ub0a8\uaca8 \ub480\uc5b4. \uac19\uc774 \ub9cc\uc9c0\ub294 \ud3b8\uc774 \ub354 \ube60\ub974\ub2c8\uae4c."," \ub124\uac00 \uc624\uba74 \uc124\uba85\uc744 \uc904\uc5ec\ub3c4 \ub3fc\uc11c \ud3b8\ud574.")
B.chy=new A.oQ(u.a9,u.fZ,"\ub77c\uc6b4\uc9c0 \ucfe0\uc158 \uc704\uce58\ub97c \uc870\uae08 \ubc14\uafe8\uc5b4. \ub124\uac00 \uc549\uae30 \ubd88\ud3b8\ud558\uba74 \ub2e4\uc2dc \ub458\uac8c.","\uacc4\uc18d \ubcf4\uace0 \uc788\uc73c\uba74 \uc22b\uc790 \uc0c9\ub9cc \ub0a8\uc544. \uc7a0\uae50 \ub208 \uc26c\uace0 \ub2e4\uc2dc \uace8\ub77c\ub3c4 \ub3fc.","\uc624\ub298 \uc4f0\ub358 \uac74 \uc815\ub9ac\ud588\uc5b4. \uc870\uc6a9\ud788 \uc788\uace0 \uc2f6\uc73c\uba74 \ub9d0 \uc548 \ud574\ub3c4 \uad1c\ucc2e\uc544.","\ubc16\uc5d0 \ub098\uac00\uba74 \uc6d0\ub2e8 \uac00\uac8c \uc55e\ub9cc \ucc9c\ucc9c\ud788 \ubcf4\uace0 \uc2f6\uc5b4. \ub124 \ucde8\ud5a5\ub3c4 \uad81\uae08\ud558\uace0."," \ub124\uac00 \ud3b8\ud55c \ucabd\uc744 \uba3c\uc800 \ub9d0\ud574 \uc918."," \ub124 \uc790\ub9ac\ub294 \ub0b4\uac00 \uc54c\uc544\ubcfc \uc218 \uc788\uac8c \ud574 \ub480\uc5b4."," \uae30\ub2e4\ub9ac\ub294 \ub3d9\uc548 \ub124 \uc0dd\uac01\uc774 \ub098\uc11c \ud558\ub098 \ub354 \ub9cc\ub4e4\uc5c8\uc5b4.")
B.chA=new A.oQ(u.g,u.g,"\uc9c0\uae08\ubd80\ud130 \uc7a5 \uc2dc\uc791 \uc804\uae4c\uc9c0 \ud560 \uc77c \uc138 \uac1c. \uc6b0\uc120\uc21c\uc704\ub294 \ub124\uac00 \uace8\ub77c.","\uacb0\uc815\ud588\uc73c\uba74 \uccb4\uacb0 \uc870\uac74\uae4c\uc9c0 \ud655\uc778. \ub9dd\uc124\uc774\ub294 \uc2dc\uac04\ub3c4 \ube44\uc6a9\uc774\uc57c.","\ub9c8\uac10\ub410\uc5b4. \uc798\ud55c \uac74 \ub0a8\uae30\uace0 \ud2c0\ub9b0 \uac74 \ub0b4\uc77c \uc21c\uc11c\uc5d0 \ub123\uc790.","\uc8fc\ub9d0\uc774\ub77c\uace0 \uacc4\ud68d\uc774 \uc5c6\ub294 \uac74 \uc544\ub2c8\uc57c. \ub300\uc2e0 \ub124\uac00 \uc6d0\ud558\ub294 \uc2dc\uac04\ubd80\ud130 \ub9d0\ud574."," \uc774\ubc88\uc5d4 \ub0b4\uac00 \ud1b5\ubcf4\ud558\uc9c0 \uc54a\uace0 \uba3c\uc800 \ubb3c\uc5b4\ubcf4\ub294 \uac70\uc57c."," \ub124 \uc77c\uc815\uc740 \ub0b4 \ud45c\uc5d0 \ub530\ub85c \ube44\uc6cc \ub480\uc5b4."," \ub108\ub791 \ub9de\ucd98 \uacc4\ud68d\uc774\uba74 \uc911\uac04\uc5d0 \ubc14\ub00c\uc5b4\ub3c4 \ub2e4\uc2dc \uc9dc\uba74 \ub3fc.")
B.chv=new A.oQ("assets/images/production_soft_painted/park_haeun/02_gentle_smile_v3.png",u.dy,"\ub2e4\ub4e4 \ubc14\ube60 \ubcf4\uc5ec\ub3c4 \ub3c4\uc6c0\uc744 \uc6d0\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\uc57c. \ub108\ubd80\ud130 \uc5b4\ub5a4\uc9c0 \ub9d0\ud574 \uc918.","\uc190\uc775 \ubcf4\uae30 \uc804\uc5d0 \uc228 \ud55c\ubc88 \uc26c\uc790. \uc9c0\uae08 \ud544\uc694\ud55c \uac8c \uc815\ubcf4\uc778\uc9c0 \uc704\ub85c\uc778\uc9c0\ub3c4 \ub2e4\ub974\ub2c8\uae4c.","\uc624\ub298\uc740 \ub124 \uc598\uae30\ub97c \uba3c\uc800 \ub4e4\uc744\uac8c. \ub098\ub3c4 \ub05d\ub098\uba74 \ub0b4 \uc598\uae30 \uc870\uae08 \ud574\ub3c4 \ub3fc?","\uc8fc\ub9d0 \uacc4\ud68d\uc740 \uac19\uc774 \uc815\ud574\uc57c \uc990\uac81\uc9c0. \uc26c\uace0 \uc2f6\uc740 \ub9c8\uc74c\ub3c4 \uc77c\uc815\uc5d0 \ub123\uc790."," \ub124\uac00 \uc194\uc9c1\ud558\uac8c \ub9d0\ud574 \uc8fc\uba74 \ub098\ub3c4 \ub35c \uc9d0\uc791\ud574\ub3c4 \ub3fc."," \ub124 \uc55e\uc5d0\uc11c\ub294 \ub098\ub3c4 \uad1c\ucc2e\uc740 \ucc99\uc744 \uc870\uae08 \ub35c \ud558\uac8c \ub3fc."," \uc624\ub298 \ub124\uac00 \uc624\uae38 \uae30\ub2e4\ub838\uc5b4. \uadf8\ub0e5 \uac19\uc774 \uc788\uace0 \uc2f6\uc5b4\uc11c.")
B.cht=new A.oQ(u.a6,u.ha,"\uc624\ub298 \ubd84\uc704\uae30 \uc880 \ub2e4\ub974\uc9c0 \uc54a\uc544? \uc7a5 \uc5f4\ub9ac\uae30 \uc804\uc5d0 \ub2e4\ub4e4 \ud45c\uc815\ubd80\ud130 \ubcfc\uae4c?","\ubc29\uae08 \ub2e4\ub4e4 \uac19\uc740 \uc22b\uc790\uc5d0\uc11c \uba48\ucdc4\uc5b4. \uadf8\uac8c \uae30\ud68c\uc778\uc9c0 \uac81\uc778\uc9c0 \ud655\uc778\ud574 \ubcf4\uc790.","\ub05d\ub0ac\ub2e4! \uc774\uc81c \uc22b\uc790 \ub9d0\uace0 \uc624\ub298 \uc9c4\uc9dc \ub180\ub780 \uc21c\uac04 \ud558\ub098\uc529 \ub9d0\ud558\uae30.","\uc8fc\ub9d0\uc774\uba74 \uc0c8\ub85c\uc6b4 \ub370 \uac00 \ubcf4\uc790. \ub2f9\uc7a5 \ub098\uac00\uc790\ub294 \uac74 \uc544\ub2c8\uace0, \uac19\uc774 \uacc4\ud68d\ubd80\ud130!"," \ub124 \ubc18\uc751\uc740 \uc774\uc0c1\ud558\uac8c \uc81c\uc77c \uba3c\uc800 \ubcf4\uc774\ub354\ub77c."," \uc0ac\uc2e4 \ub124\uac00 \uc624\uba74 \ubd84\uc704\uae30\uac00 \uc5b4\ub5bb\uac8c \ubc14\ub014\uc9c0 \uae30\ub2e4\ub838\uc5b4."," \ub108\ud55c\ud14c\ub294 \uc7a5\ub09c \ub9d0\uace0 \uc9c4\uc9dc \uac71\uc815\ud55c \uac83\ub3c4 \ub9d0\ud560 \uc218 \uc788\uc5b4.")
B.chu=new A.oQ("assets/images/production_soft_painted/oh_jiwoo/02_cheerful_fang_wave_v1.png",u.et,"\uc624\ub298 \uccab \uac00\uc124. \ub2e4\ub4e4 \ud655\uc2e0\ud558\ub294 \uc885\ubaa9\uc77c\uc218\ub85d \ud55c \ubc88 \ub354 \uc758\uc2ec\ud574\uc57c \ud55c\ub2e4.","\uc18d\ubcf4\ucc98\ub7fc \ubcf4\uc774\ub294 \uc7a1\uc74c\uc774 \uc81c\uc77c \uc704\ud5d8\ud558\uc9c0. \ubc18\ub300 \uc124\uba85\ubd80\ud130 \ud558\ub098 \uc138\uc6cc \ubcfc\ub798?","\uc624\ub298 \ub0b4 \uc608\uce21\ub3c4 \ud558\ub098 \ud2c0\ub838\uc5b4. \ub124\uac00 \uc6c3\uae30 \uc804\uc5d0 \ubc18\ub840\ubd80\ud130 \uac19\uc774 \ucc3e\uc790.","\uc8fc\ub9d0 \ud1a0\ub860 \uc8fc\uc81c \uc811\uc218 \uc911. \uacb0\ub860 \uc5c6\ub294 \uc598\uae30\ub3c4 \uc7ac\ubbf8\uc788\uc73c\uba74 \ud569\uaca9."," \ub124 \ubc18\ub860\uc740 \uaf64 \uc4f8 \ub9cc\ud574\uc11c \ub530\ub85c \uc801\uc5b4 \ub480\uace0."," \ub108\ud55c\ud14c \ud2c0\ub9b0 \uac78 \ub4e4\ud0a4\ub294 \uac74 \uc804\ubcf4\ub2e4 \ub35c \uc2eb\uc5b4."," \ub124 \uc55e\uc5d0\uc11c\ub294 \ubaa8\ub978\ub2e4\uace0 \ub9d0\ud574\ub3c4 \ub2e4\uc74c \uc598\uae30\uac00 \uc774\uc5b4\uc9c0\ub2c8\uae4c \uc88b\uc544.")
B.chz=new A.oQ("assets/images/production_soft_painted/yoon_chaea/02_soft_smile_wave_v1.png",u.ga,"\uc624\ub298 \uc77c\uc815\uc740 \uc5b4\uc81c\uc640 \uac19\uc544 \ubcf4\uc5ec\ub3c4 \uc804\uc81c\uac00 \ud558\ub098 \ub2ec\ub77c. \uba3c\uc800 \ucc3e\uc73c\uba74 \ub9d0\ud574 \uc904\uac8c.","\uac00\uaca9 \ud558\ub098\ub9cc \ubcf4\uba74 \ub2a6\uc5b4. \uadf8 \uc22b\uc790\ub97c \ub9cc\ub4e0 \uad6c\uc870\uac00 \uc544\uc9c1 \uc720\uc9c0\ub418\ub294\uc9c0 \ubd10.","\uc624\ub298 \uacb0\uacfc\ub294 \uc815\ub9ac\ud588\uc5b4. \uacb0\ub860\ubcf4\ub2e4 \ub124\uac00 \uc911\uac04\uc5d0 \ubc84\ub9b0 \uac00\uc815\uc774 \uad81\uae08\ud574.","\uc0ac\ub78c \uc801\uc740 \uacf3\uc774\uba74 \ub098\uac00\ub3c4 \uad1c\ucc2e\uc544. \uacc4\ud68d\uc740 \ubbf8\ub9ac \uc138\uc6b0\ub294 \ud3b8\uc774 \uc88b\uace0."," \ub124 \uc0dd\uac01\uc740 \uacb0\ub860 \uc804\uc5d0 \ub4e4\uc5b4\ub3c4 \uad1c\ucc2e\uc744 \uac83 \uac19\uc544."," \uc544\uc9c1 \ub35c \uc815\ub9ac\ub410\uc9c0\ub9cc \ub108\ud55c\ud14c\ub294 \uc911\uac04\ubd80\ud130 \ub9d0\ud574 \ubcfc\uac8c."," \ub0b4 \uacc4\ud68d\uc5d0 \ub124\uac00 \uc788\ub294 \uac74 \uc774\uc81c \ubcc4\ub3c4 \uac00\uc815\uc774 \uc544\ub2c8\uc57c.")
B.Pl=new A.J(B.hH,[B.chw,B.chx,B.chy,B.chA,B.chv,B.cht,B.chu,B.chz],A.an("J<j,oQ>"))
B.cj7=new A.oT("\uc815\ub2f5 \ub300\uc2e0 \uae30\ub85d\ubd80\ud130 \ubd10. \ud68c\uc0ac\uac00 \uc804\uc5d0 \ud55c \ub9d0\uc744 \uc2e4\uc81c\ub85c \uba87 \ubc88 \uc9c0\ucf30\ub294\uc9c0 \ud655\uc778\ud574 \ubd10.","\ub2e4\uc74c \uacf5\uc2dc\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc57d\uc18d\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ub300\uc870\ud558\uba74 \ub3fc.","\uacfc\uac70\uc758 \uc57d\uc18d \uc774\ud589\ub9cc\uc73c\ub85c \uc55e\uc73c\ub85c\uc758 \uc131\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.cj2=new A.oT("\ud654\uba74 \uc124\uba85\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uc791\ub3d9\ud55c \uac78 \ubd10. \uccb4\uacb0\uac00\ub098 \uc81c\ud488 \uacb0\uacfc\ucc98\ub7fc \uc190\uc5d0 \uc7a1\ud788\ub294 \uac83\ubd80\ud130.","\ud45c\uc2dc\ub41c \uac12\uacfc \uc2e4\uc81c \uccb4\uacb0\xb7\uc791\ub3d9 \uacb0\uacfc\uac00 \ub2e4\uc2dc \uc77c\uce58\ud558\ub294\uc9c0 \ud655\uc778\ud574.","\uccb4\uacb0\uacfc \uc81c\ud488 \uc791\ub3d9\ub9cc\uc73c\ub85c \uc0ac\uc5c5 \uac00\uce58 \uc804\uccb4\ub97c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.cj6=new A.oT("\uac00\uaca9\uc120\uc758 \uacb0\uc774 \uac11\uc790\uae30 \ub2ec\ub77c\uc9c4 \uc790\ub9ac\ubd80\ud130 \ubd10. \uc774\uc0c1\ud558\ub2e4\ub294 \ub290\ub08c\uc740 \ub2f5\uc774 \uc544\ub2c8\ub77c \ud655\uc778 \uc2e0\ud638\uc57c.","\ub2e4\uc74c \uc6c0\uc9c1\uc784\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub9ac\ub4ec\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ubcf4\uace0 \ud310\ub2e8\ud574.","\uac00\uaca9\uc758 \uc774\uc0c1 \uc9d5\ud6c4\ub294 \uc6d0\uc778\uc774 \uc544\ub2c8\ub77c \ucd94\uac00 \ud655\uc778\uc774 \ud544\uc694\ud55c \uc2e0\ud638\ub2e4.")
B.cj8=new A.oT("\uc0b4 \uc774\uc720\ubcf4\ub2e4 \ub098\uc62c \uc870\uac74\ubd80\ud130 \uc801\uc5b4. \uc2e4\ud589 \uc21c\uc11c\uac00 \uc5c6\uc73c\uba74 \uc88b\uc740 \uacc4\ud68d\ub3c4 \uae09\ud560 \ub54c \uc5c9\ucf1c.","\uc815\ud55c \ub9c8\uac10\uacfc \ucca0\uc218 \uc870\uac74\uc744 \uc2e4\uc81c\ub85c \uc9c0\ud0ac \uc218 \uc788\ub294\uc9c0 \uba3c\uc800 \uc810\uac80\ud574.","\uc2e4\ud589 \uacc4\ud68d\uc774 \uc88b\uc544\ub3c4 \uc218\uc694\uc640 \uac00\uaca9\uc774 \ub9de\ub294\uc9c0\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ud55c\ub2e4.")
B.cj5=new A.oT("\uc88b\uc740 \ub9d0\ubcf4\ub2e4 \ub204\uac00 \ub9d0\ud558\uc9c0 \ubabb\ud588\ub294\uc9c0 \ubd10. \uc774\ud574\uad00\uacc4\uac00 \ub9c9\ud78c \uc790\ub9ac\uc5d0 \ube60\uc9c4 \uc815\ubcf4\uac00 \uc788\uc744 \uc218 \uc788\uc5b4.","\ubc18\ub300 \uc758\uacac\uc744 \ub0bc \uc218 \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uac19\uc740 \uc774\uc57c\uae30\uac00 \ub098\uc624\ub294\uc9c0 \ubb3c\uc5b4\ubd10.","\uc0ac\ub78c\ub4e4\uc758 \ubd84\uc704\uae30\ub97c \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub0b4\ubd80 \uc0ac\uc2e4\ucc98\ub7fc \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.cj4=new A.oT("\uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc774\ub984\uc744 \ub2e4\uc2dc \uaebc\ub0b4\ub294\uc9c0 \ubd10. \ud55c \ubc88\uc758 \uc18c\ubb38\ubcf4\ub2e4 \ubc18\ubcf5\ub418\ub294 \uc218\uc694\uac00 \uc911\uc694\ud574.","\uadf8 \uad00\uc2ec\uc774 \uc2e4\uc81c \uc7ac\uad6c\ub9e4\ub098 \ub9e4\ucd9c \uc22b\uc790\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud574 \ubd10.","\uc720\ud589\uc758 \uc804\uc870\ub294 \uc77c\uc2dc\uc801\uc778 \uc18c\ubb38\uc77c \uc218 \uc788\uc73c\uba70 \ub9e4\ucd9c\uc744 \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.cj3=new A.oT("\uc9c0\uae08 \ubbff\ub294 \uc774\uc720\uac00 \ud2c0\ub9ac\ub294 \uacbd\uc6b0\ub97c \ud558\ub098 \ub9cc\ub4e4\uc5b4 \ubd10. \ubc18\ub840\uac00 \ubc84\ud2f0\uba74 \uac00\uc124\ub3c4 \ub2e4\uc2dc \ubd10\uc57c\uc9c0.","\uc5b4\ub5a4 \uc0ac\uc2e4\uc774 \ub098\uc624\uba74 \ub124 \uc0dd\uac01\uc744 \ubc14\uafc0\uc9c0 \uba3c\uc800 \uc815\ud574 \ub46c.","\ubc18\ub840 \ud558\ub098\ub9cc\uc73c\ub85c \uc6d0\ub798 \uac00\uc124 \uc804\uccb4\uac00 \ud2c0\ub838\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.cj1=new A.oT("\ud558\ub8e8 \uac00\uaca9\ubcf4\ub2e4 \uad6c\uc870\ub97c \ubd10. \ub124 \uc804\uc81c\uac00 \ubb34\uc5c7\uc774\uace0 \uc5b8\uc81c \uae68\uc9c0\ub294\uc9c0\ubd80\ud130 \uc801\uc5b4.","\ud575\uc2ec \uc804\uc81c\uac00 \ubc14\ub00c\uc5c8\uc744 \ub54c \uc190\uc2e4 \ubc94\uc704\uac00 \uc5b4\ub514\uae4c\uc9c0\uc778\uc9c0 \ub2e4\uc2dc \uacc4\uc0b0\ud574.","\uc7a5\uae30 \uad6c\uc870\ub3c4 \uc804\uc81c\uac00 \ubc14\ub00c\uba74 \uae68\uc9c0\uba70 \ubbf8\ub798 \uacb0\uacfc\ub97c \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.")
B.bhy=new A.J(B.hH,[B.cj7,B.cj2,B.cj6,B.cj8,B.cj5,B.cj4,B.cj3,B.cj1],A.an("J<j,oT>"))
