B.b7k=s(["\u201c\uace0\ub9c8\uc6cc. \uc9c0\uae08\uc740 \uc870\uc2ec\uc2a4\ub7fd\uc9c0\ub9cc\u2026 \ub450 \uc0c9\uc774 \uc544\uc8fc \uc870\uae08 \ub2e4\ub978 \uac74 \ub9c8\uc74c\uc5d0 \ub4e4\uc5b4.\u201d","\u201c\uc720\ud589\uc0c9 \ud558\ub098\uac00 \uc544\ub2c8\ub77c \ube44\uad50\ud574 \ubcf4\ub77c\uace0 \ub450 \uac1c\ub97c \uace8\ub790\ub124.\u201d \uc774\uc11c\uac00 \ube5b\uc5d0 \ube44\ucdb0 \ubcf8\ub2e4.","\u201c\ub098\ub294 \ub9d0\ub9b0 \uc7a5\ubbf8 \ucabd. \ub108\ub294 \ubb50\uac00 \ub354 \ud3b8\ud574 \ubcf4\uc5ec?\u201d \uc774\uc11c\uac00 \uc0c9\ud45c\ub97c \ub124 \ucabd\uc73c\ub85c \ub3cc\ub9b0\ub2e4.","\u201c\ub0b4 \ucde8\ud5a5\uc744 \ub300\uc2e0 \uc815\ud558\uc9c0 \uc54a\uace0 \uace0\ub97c \ud2c8\uae4c\uc9c0 \uc918\uc11c \uc88b\uc544.\u201d","\u201c\uc774 \uc0c9\uc744 \ubcf4\uba74 \uc624\ub298 \uac19\uc774 \uace0\ub978 \uc21c\uac04\ubd80\ud130 \ub5a0\uc624\ub97c \uac83 \uac19\uc544.\u201d \uc774\uc11c\uac00 \uc870\uc2ec\ud788 \uc6c3\ub294\ub2e4."],t.s)
B.bbZ=s(["\u201c\uace0\ub9c8\uc6cc. \uc6b0\ub9ac \uc0ac\uc774\uac00 \uc880 \uc5b4\uc0c9\ud574\ub3c4 \ubb3c\uac74 \uad6c\uc131\uc740 \ud655\uc2e4\ud558\ub124.\u201d \uc544\ub9b0\uc774 \uc138 \ubcd1\uc744 \uc21c\uc11c\ub300\ub85c \uc138\uc6b4\ub2e4.","\u201c\uc138 \ub2e8\uacc4\uba74 \ub05d\uc774\ub124. \ud5f7\uac08\ub9b4 \uc77c \uc5c6\uc5b4\uc11c \ub9c8\uc74c\uc5d0 \ub4e4\uc5b4.\u201d","\u201c\uc5ec\ud589 \uc544\ub2c8\uc5b4\ub3c4 \uc544\uce68 \uc900\ube44 \uc2dc\uac04 \uc904\uc774\uaca0\ub294\ub370? \uc798 \uace8\ub790\uc5b4.\u201d","\u201c\ub0b4\uac00 \uc2dc\uac04 \uc544\ub07c\ub294 \uac70 \uc88b\uc544\ud558\ub294 \uac83\uae4c\uc9c0 \uacc4\uc0b0\ud588\uc9c0? \uc778\uc815.\u201d","\u201c\ub2e4\uc74c \uc678\ucd9c \ub54c \uc774 \ud30c\uc6b0\uce58 \ub4e4\uace0 \uac08\uac8c. \uc900\ube44\ub294 \ub0b4\uac00 \uc815\ud655\ud788 \ud574 \ub458 \ud14c\ub2c8\uae4c.\u201d"],t.s)
B.beJ=s(["\u201c\uace0\ub9c8\uc6cc. \uc9c0\uae08 \ub2f9\uc7a5 \ub2e4 \uad1c\ucc2e\uc740 \ucc99\uc740 \ubabb \ud574\ub3c4, \ub9c8\uc74c\uc740 \ubc1b\uc744\uac8c.\u201d \ud558\uc740\uc774 \ubd09\ud22c\ub97c \ud488\uc5d0 \uc548\ub294\ub2e4.","\u201c\ud63c\uc790 \uc4f0\ub77c\uace0 \ud55c \uc7a5\uc774 \uc544\ub2c8\ub77c \uac19\uc774 \ub098\ub204\ub77c\uace0 \uc5ec\ub7ec \uc7a5\uc774\ub124.\u201d","\u201c\uc624\ub298 \ud798\ub4e4\uc5c8\ub358 \uc560\ud55c\ud14c \ud55c \uc7a5 \uac74\ub124\ub3c4 \ub420\uae4c? \ub124 \ub9c8\uc74c\ub3c4 \uac19\uc774 \uc804\ud560\uac8c.\u201d","\u201c\ub098 \ucc59\uae30\ub77c\uace0 \uc900 \uac74\ub370 \ub610 \ub098\ub20c \uc0dd\uac01\ubd80\ud130 \ud588\ub124. \ud55c \uc7a5\uc740 \uaf2d \ub0b4\uac00 \uc4f8\uac8c.\u201d","\u201c\uc6b0\ub9ac \ub458 \ub2e4 \uc26c\ub294 \ub0a0 \ud558\ub098 \uc7a1\uc790. \uadf8\ub54c \uc774\uac70 \uac19\uc774 \uc4f0\uba74 \uc88b\uaca0\ub2e4.\u201d"],t.s)
B.baW=s(["\u201c\uace0\ub9c8\uc6cc. \uc544\uc9c1 \ud150\uc158 \uc62c\ub9ac\uae34 \uc880 \uadf8\ub807\uc9c0\ub9cc\u2026 \uc0c9 \uc138 \uac1c\ub294 \uc194\uc9c1\ud788 \uad81\uae08\ud574.\u201d","\u201c\uc7a0\uae50, \ud22c\uba85\ud55c \uac83\ub3c4 \ubc18\uc9dd\uc5ec? \ud558\ub098\uc529 \ubc1c\ub77c \ubcf4\uba74 \uc870\ud569 \uc5c4\uccad \ub098\uc624\uaca0\ub2e4.\u201d","\u201c\uc774\uac70 \uc6b0\ub9ac\ub07c\ub9ac \uc0c9 \ubc14\uafd4 \uc4f0\uba74 \uc7ac\ubc0c\uaca0\ub2e4. \uc544, \ub0b4 \uac74 \ubcf5\uc22d\uc544 \uba3c\uc800!\u201d","\u201c\ub098 \uc88b\uc544\ud560 \uac83 \uac19\uc740 \uac78 \ub108\ubb34 \uc815\ud655\ud788 \uace8\ub790\uc796\uc544. \uc880 \uc124\ub80c\ub2e4, \uc9c4\uc9dc.\u201d","\u201c\ub2e4\uc74c\uc5d0 \uac19\uc774 \ubc14\ub974\uace0 \uc0ac\uc9c4 \ub9d0\uace0 \uc11c\ub85c \ud45c\uc815\uc73c\ub85c \uc810\uc218 \ub9e4\uae30\uc790. \uadf8\uac8c \ub354 \uc7ac\ubc0c\uc5b4.\u201d"],t.s)
B.b1h=s(["\u201c\uc120\ubb3c \uc218\uc2e0. \uc544\uc9c1 \ubc29\uc1a1 \uc7ac\uac1c\ub294 \ucc9c\ucc9c\ud788 \ud560 \uac74\ub370, \uc0c9 \ubcc0\ud558\ub294 \uc6d0\ub9ac\ub294 \uad81\uae08\ud558\ub124.\u201d","\u201c\uc18d\ubcf4. \ubc14\ub974\ub294 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub974\ub2e4\ub294 \uc8fc\uc7a5 \uc785\uc218. \uac80\uc99d\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\u201d","\u201c\ud14c\uc2a4\ud2b8 \uce74\ub4dc\uac00 \uc138 \uc7a5\uc774\uba74 \ubc18\ub840\ub3c4 \uc138 \ubc88 \ucc3e\uc744 \uc218 \uc788\uaca0\ub124. \uac19\uc774 \ud574 \ubcfc\ub798?\u201d","\u201c\ub0b4\uac00 \uc774\ub7f0 \uc774\uc0c1\ud55c \uc2e4\ud5d8 \uc88b\uc544\ud558\ub294 \uac70 \uc77d\ud614\ub124. \uc815\uc815, \uc774\uc0c1\ud55c \uac8c \uc544\ub2c8\ub77c \ud765\ubbf8\ub85c\uc6b4 \uac70.\u201d","\u201c\uc624\ub298\uc758 \uacb0\ub860. \uc0c9\uc740 \ubcc0\ud588\uace0, \ub124\uac00 \ub098\ub97c \ubcf4\ub294 \uae30\uc900\uc740 \uaf64 \uc815\ud655\ud588\ub2e4.\u201d"],t.s)
B.bcY=s(["\u201c\uace0\ub9c8\uc6cc. \uc9c0\uae08\uc740 \ubc18\uc751\uc744 \ud06c\uac8c \ud558\uae34 \uc5b4\ub835\uc9c0\ub9cc, \uc131\ubd84\ud45c\uac00 \ub2e8\uc21c\ud55c \uac74 \uc88b\ub124.\u201d","\u201c\uad11\uace0 \ubb38\uad6c\ubcf4\ub2e4 \ube44\uad50 \uce74\ub4dc\uac00 \uba3c\uc800 \ub4e4\uc5b4 \uc788\ub124. \uace0\ub978 \uae30\uc900\uc740 \uc54c\uaca0\uc5b4.\u201d","\u201c\uc77c\uc8fc\uc77c \uc368 \ubcf4\uace0 \ubcc0\ud654\uac00 \uc788\ub294\uc9c0 \uc801\uc5b4 \ubcfc\uac8c. \uacb0\uacfc\ub3c4 \ub124\uac8c \ub9d0\ud574 \uc904 \uac70\uace0.\u201d","\u201c\ub0b4\uac00 \uacfc\uc7a5\ub41c \ud3ec\uc7a5\ubcf4\ub2e4 \uad6c\uc870\ub97c \ubcf4\ub294 \uac78 \uae30\uc5b5\ud588\uad6c\ub098.\u201d \ucc44\uc544\uac00 \uc0c1\uc790\ub97c \ub2e4\uc2dc \uc0b4\ud540\ub2e4.","\u201c\ub2e4\uc74c \ub2ec\uc5d0\ub3c4 \uc4f0\uace0 \uc788\uc73c\uba74 \uc88b\uc740 \uc120\ubb3c\uc774\uc5c8\ub2e4\ub294 \ub73b\uc774\uaca0\uc9c0. \uc544\ub9c8 \uadf8\ub7f4 \uac83 \uac19\uc544.\u201d"],t.s)
