B.b1O=s(["\ucc98\uc74c\uc5d0 \ubb58 \ubcf4\uace0 \uc0c0\ub294\uc9c0 \ub2e4\uc2dc \ubcf4\uc5ec \uc918.","\uc9c1\uc811 \ubcf8 \uc0ac\uc2e4\uc774\ub791 \ub124 \ucd94\uce21\uc744 \ub098\ub220 \ubd10."],t.s)
B.b_J=s([B.b2v,B.bcL,B.b6Z,B.b1O],t.rj)
B.b1W=s(["\uc54c\uc558\uc5b4. \ub2e4\uc74c\uc5d0 \uac19\uc740 \uc77c\ub9cc \uc5c6\uc73c\uba74 \ub3fc.","\ub3c4\uc6c0 \ub410\ub2e4\uba74 \ub410\uc5b4.","\ubb50\uac00 \ubd88\uc548\ud55c \uac74\ub370? \ud574\uacb0\ud560 \uc77c\uc774\uba74 \uac19\uc774 \ubcf4\uc790.","\uc88b\uc544. \ubcf5\uc7a1\ud558\uac8c\ub9cc \uc548 \ud558\uba74 \ub3fc."],t.s)
B.b1F=s(["\uc9c1\uc811 \ud655\uc778\ud55c \uac74 \ubb50\uc57c?","\ub0b4\uc77c \ubb58 \ubcfc \uac74\ub370?","\ud55c \ubc88 \ub354 \ud574\ub3c4 \uac19\uc740 \uacb0\uacfc\uac00 \ub098\uc640?"],t.s)
