B.cmO=new A.nv(B.beL,B.b_Y,B.b25,B.b8N,B.b10,B.b8G,"\uac19\uc740 \uc598\uae30\uac00 \uc790\uafb8 \ub3cc\uc544\uc624\ub124. \ub124 \ub9c8\uc74c\uc740 \uadf8\ub300\ub85c\uc57c?","\uc9c0\uae08\uae4c\uc9c0\ub294 \ubcf8\uc804 \uc544\ub798\uc57c. \ub124\uac00 \ub9d0\ud55c \uc218\uc775\uc740 \uc5b4\ub514\uc5d0\uc11c \ub09c \uac78\uae4c?","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub9c8\uc74c\uc5d0 \uac78\ub9b0 \ub2e4\ub978 \uc190\uc2e4\uc774 \uc788\uc5b4?","\uc624\ub298\uc740 \ub0b4\ub824\uac14\uc5b4. \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc744 \ub9d0\ud55c \uac78\uae4c?","\uc624\ub298\uc740 \uc62c\ub790\uc5b4. \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub77c\ub294 \ub73b\uc774\uc57c?")
B.b_B=s(["\ud655\uc778\ud588\uc5b4.","\uc88b\uc544, \uc774\ud574\ud588\uc5b4.","\ub124 \uc758\uacac\ub3c4 \uc54c\uaca0\uc5b4.","\ub05d\uae4c\uc9c0 \uc77d\uace0 \uc815\ub9ac\ud588\uc5b4.","\uc911\uc694\ud55c \uc598\uae30\uc778 \uac74 \uc54c\uaca0\uc5b4.","\ub124\uac00 \ub9d0\ud55c \uac70\uba74 \uc77c\ub2e8 \ubbff\uc744\uac8c."],t.s)
B.bas=s(["\uc544\uc9c1 \ub9c8\uac10 \uc804\uc774\uc57c. \uacb0\uacfc \ub098\uc628 \ub2e4\uc74c\uc5d0 \uc598\uae30\ud558\uc790.","\uc624\ub298 \uc7a5 \uc26c\uc796\uc544. \ub2e4\uc74c \uc8fc \uacc4\ud68d\uc774\ub098 \uc815\ud558\uc790.","\uc624\ub298\uc740 \uac70\uc758 \uadf8\ub300\ub85c\ub124. \uacc4\ud68d\uc5d0\uc11c \ubc97\uc5b4\ub09c \uac83\ub9cc \ubd10.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\uc57c. \uc695\uc2ec\ub0bc \uc120\ubd80\ud130 \uc815\ud574.","\uc624\ub298\uc740 \ubc8c\uc5c8\uc9c0\ub9cc \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c.","\uc624\ub298\uc740 \uc783\uc5c8\uc5b4\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc740 \ub0a8\uc544 \uc788\uc5b4. \uadf8\ub9cc\ub458 \uc120 \ub2e4\uc2dc \ubd10.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c. \uc5bc\ub9c8\uae4c\uc9c0 \uc904\uc77c\uc9c0 \ubc14\ub85c \uc815\ud574."],t.s)
B.b3Y=s(["\uc190\ud574 \ubd24\uc73c\uba74 \ub2e4\uc74c\uc5d4 \uc5bc\ub9c8\ub9cc \uc0b4\uc9c0 \uc9c0\uae08 \uc815\ud574.","\ud2c0\ub9b0 \uac74 \ubc14\ub85c \uace0\uce58\uba74 \ub3fc. \ub0b4\uc77c \ud560 \uc77c\ubd80\ud130 \ud558\ub098 \uc815\ud558\uc790."],t.s)
B.b48=s(["\ubc8c\uc5c8\uc73c\uba74 \ub410\uc5b4. \uc774\uc81c \uc5b4\ub514\uc11c \uba48\ucd9c\uc9c0\ub9cc \uc815\ud574.","\uc798\ub410\ub124. \ub2e4\uc74c\uc5d0\ub3c4 \ubcfc \uc22b\uc790\ub791 \ub0a0\uc9dc\ub97c \ubc14\ub85c \uc801\uc790."],t.s)
B.b09=s(["\ubb58 \uc0b4\uc9c0\ubcf4\ub2e4 \uc5b8\uc81c \uc0ac\uace0 \uc5b8\uc81c \uadf8\ub9cc\ub458\uc9c0\ubd80\ud130 \uc815\ud574.","\ub9d0\ub9cc \uc88b\uc740 \ud68c\uc0ac \ub9d0\uace0 \uc57d\uc18d\ud55c \uac78 \uc81c\ub54c \ud588\ub294\uc9c0 \ubd10."],t.s)
