B.b3O=s([B.b3Y,B.b48,B.b09,B.bep],t.rj)
B.beV=s(["\uc0ac\uacfc\ub294 \ubc1b\uc558\uc5b4.","\ub3c4\uc6c0\uc774 \ub410\ub2e4\uba74 \ub410\uc5b4.","\ubb50\uac00 \uc81c\uc77c \ubd88\uc548\ud574? \ub0b4\uac00 \ud560 \uc218 \uc788\ub294 \uac74 \ub9e1\uc744\uac8c.","\uc88b\uc544. \uba87 \uc2dc\uc5d0 \ud560\uc9c0\ub9cc \uc815\ud558\uc790."],t.s)
